text:
* {
  box-sizing: border-box;
}
:root {
  font-family: Inter, 'Microsoft YaHei', 'Helvetica Neue', system-ui, sans-serif;
  color: #ffffff;
  background: #23280b;
  font-synthesis: none;
  --color-canvas: #d9cdad;
  --color-table: #465016;
  --color-table-deep: #23280b;
  --color-moss: #616a37;
  --color-charcoal: #2f2e25;
  --color-leather: #764b41;
  --color-leather-dark: #594d40;
  --color-cream: #ffffff;
  --color-accent: #ccff00;
  --color-command: #c6a15b;
  --color-command-hover: #d2b06c;
  --color-danger: #ff3b30;
  --color-secondary: #0057ff;
  --color-focus: #00ff00;
  --ink: var(--color-table-deep);
  --ink-soft: var(--color-charcoal);
  --table: var(--color-table);
  --table-deep: var(--color-table-deep);
  --paper: var(--color-cream);
  --muted: var(--color-canvas);
  --gold: var(--color-accent);
  --gold-deep: var(--color-moss);
  --red: var(--color-danger);
  --green: var(--color-accent);
  --blue: var(--color-secondary);
  --line: rgba(255, 255, 255, 0.18);
  --control-transition: 160ms ease;
}
body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
}
button,
input,
select,
textarea {
  font: inherit;
  letter-spacing: 0;
}
button {
  cursor: pointer;
  transition:
    transform var(--control-transition),
    background-color var(--control-transition),
    border-color var(--control-transition),
    color var(--control-transition);
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
a:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}
.home-shell {
  min-height: 100vh;
  display: grid;
  grid-template-rows: 68px minmax(680px, 1fr) 42px;
  background: var(--ink);
}
.lobby-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 clamp(15px, 2.5vw, 38px);
  border-bottom: 1px solid rgba(246, 242, 232, 0.13);
  background: var(--ink);
  z-index: 50;
}
.brand-lockup,
.header-actions,
.service-state,
.home-footer {
  display: flex;
  align-items: center;
}
.brand-lockup {
  gap: 11px;
}
.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  color: var(--ink);
  background: var(--gold);
  border: 1px solid #ffe091;
  font:
    900 14px/1 Arial Black,
    sans-serif;
  transform: rotate(-3deg);
}
.brand-lockup div {
  display: grid;
  gap: 1px;
}
.brand-lockup strong {
  font-size: 16px;
}
.brand-lockup span:last-child {
  color: rgba(246, 242, 232, 0.55);
  font-size: 11px;
  font-weight: 700;
}
.header-actions {
  gap: 10px;
}
.audio-control {
  position: relative;
}
.header-icon-button {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid var(--color-command);
  background: transparent;
  color: var(--color-command);
}
.audio-popover {
  position: absolute;
  z-index: 90;
  top: calc(100% + 10px);
  right: 0;
  width: 220px;
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--color-command);
  background: var(--color-table-deep);
  color: var(--color-cream);
}
.audio-popover label {
  display: grid;
  gap: 8px;
  font-size: 11px;
  font-weight: 800;
}
.audio-popover input {
  width: 100%;
  accent-color: var(--color-command);
}
.header-auth {
  min-height: 40px;
  padding: 0 15px;
  border: 1px solid var(--gold);
  color: var(--gold);
  background: transparent;
  font-size: 12px;
  font-weight: 900;
}
.header-auth:hover {
  color: var(--ink);
  background: var(--gold);
}
.service-state {
  gap: 7px;
  min-height: 44px;
  color: rgba(246, 242, 232, 0.7);
  font-size: 11px;
  font-weight: 800;
}
.service-state i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #8c938e;
}
.state-connected i {
  background: var(--green);
  box-shadow: 0 0 0 3px rgba(86, 191, 125, 0.15);
}
.state-disconnected i {
  background: var(--red);
}
.state-read-only i {
  background: var(--gold);
}
.home-stage {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding: 22px clamp(16px, 2.4vw, 36px) 18px;
  background-color: var(--table);
  background-image:
    repeating-linear-gradient(90deg, transparent 0 4px, rgba(255, 255, 255, 0.018) 4px 5px),
    repeating-linear-gradient(0deg, transparent 0 6px, rgba(0, 0, 0, 0.025) 6px 7px);
}
.home-table-lines {
  position: absolute;
  inset: 14px;
  z-index: -1;
  border: 1px solid rgba(239, 187, 71, 0.2);
  pointer-events: none;
}
.home-table-lines::before {
  content: '';
  position: absolute;
  width: min(52vw, 760px);
  aspect-ratio: 1;
  border: 1px solid rgba(246, 242, 232, 0.07);
  border-radius: 50%;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}
.home-layout {
  width: min(100%, 1600px);
  min-height: 620px;
  height: 100%;
  margin-inline: auto;
  display: grid;
  grid-template-columns: minmax(240px, 280px) minmax(420px, 1fr) minmax(280px, 320px);
  gap: clamp(16px, 2vw, 28px);
  align-items: stretch;
}
.pve-tool {
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.pve-tool header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}
.pve-tool header svg {
  color: var(--color-accent);
  flex-shrink: 0;
}
.pve-tool header span {
  color: var(--color-canvas);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.pve-tool header h2 {
  color: var(--color-cream);
  font-size: 16px;
  font-weight: 900;
}
.pve-description {
  margin-bottom: 16px;
  color: rgba(255, 255, 255, 0.68);
  font-size: 11px;
  line-height: 1.5;
}
.pve-size-selector {
  display: flex;
  gap: 8px;
  margin: 12px 0;
}
.pve-size-selector button {
  flex: 1;
  min-height: 44px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  border: 1px solid rgba(255, 255, 255, 0.34);
  border-radius: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
}
.pve-size-selector button strong {
  font-size: 18px;
  font-weight: 900;
}
.pve-size-selector button[aria-pressed='true'] {
  border-color: var(--color-command);
  background: var(--color-command);
  color: var(--color-table-deep);
}
.pve-size-selector button:hover:not(:disabled) {
  border-color: var(--color-command-hover);
  transform: translateY(-2px);
}
.pve-start-button {
  border-radius: 0;
}
.private-room-header {
  min-height: 54px;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 0;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line);
}
.private-room-header svg {
  color: var(--color-accent);
  flex-shrink: 0;
}
.private-room-header span {
  color: var(--color-canvas);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.private-room-header h2 {
  color: var(--color-cream);
  font-size: 16px;
  font-weight: 900;
}
.profile-rail,
.room-rail {
  min-width: 0;
  align-self: center;
  border: 1px solid rgba(246, 242, 232, 0.22);
  background: rgba(14, 39, 29, 0.92);
  box-shadow: 8px 8px 0 rgba(4, 18, 13, 0.42);
}
.profile-rail {
  max-height: min(620px, calc(100vh - 154px));
}
@media (min-width: 1101px) {
  .room-rail {
    align-self: end;
    max-height: none;
    margin-bottom: 16px;
  }
}
.profile-summary {
  min-height: 94px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 17px;
  border-bottom: 1px solid var(--line);
}
.profile-avatar {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  background: var(--paper);
  color: var(--ink);
}
.profile-summary div {
  min-width: 0;
  display: grid;
  gap: 4px;
}
.profile-summary span:not(.profile-avatar) {
  color: var(--gold);
  font-size: 10px;
  font-weight: 900;
}
.profile-summary strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
}
.rail-command {
  width: 100%;
  min-height: 68px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border: 0;
  border-bottom: 1px solid var(--line);
  color: var(--paper);
  background: transparent;
  text-align: left;
}
.rail-command:hover {
  background: rgba(239, 187, 71, 0.08);
}
.rail-command > svg {
  color: var(--gold);
  flex: 0 0 auto;
}
.rail-command span {
  display: grid;
  gap: 3px;
}
.rail-command strong {
  font-size: 13px;
}
.rail-command small {
  color: rgba(246, 242, 232, 0.5);
  font-size: 10px;
}
.rating-summary {
  padding: 18px 16px;
  border-bottom: 1px solid var(--line);
}
.rating-summary header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}
.rating-summary header svg {
  color: var(--gold);
}
.rating-summary h2 {
  margin: 0;
  font-size: 15px;
}
.rating-row {
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-top: 1px solid rgba(246, 242, 232, 0.1);
  font-size: 12px;
}
.rating-row strong {
  color: var(--gold);
  font-size: 11px;
}
.rating-primary {
  min-height: 54px;
  display: grid;
  align-content: center;
  gap: 4px;
  border-top: 1px solid rgba(246, 242, 232, 0.1);
}
.rating-primary strong {
  color: var(--gold);
  font-size: 14px;
}
.rating-primary span {
  color: rgba(246, 242, 232, 0.55);
  font-size: 10px;
}
.leaderboard-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid rgba(246, 242, 232, 0.1);
}
.leaderboard-title span {
  color: var(--gold);
  font-size: 9px;
  font-weight: 900;
}
.leaderboard-title small {
  color: rgba(246, 242, 232, 0.45);
  font-size: 9px;
}
.leaderboard-list {
  max-height: 182px;
  margin: 7px 0 0;
  padding: 0;
  list-style: none;
  overflow: auto;
}
.leaderboard-list li {
  min-height: 28px;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) 42px;
  align-items: center;
  gap: 5px;
  border-top: 1px solid rgba(246, 242, 232, 0.07);
  font-size: 9px;
}
.leaderboard-list li b {
  color: rgba(246, 242, 232, 0.4);
}
.leaderboard-list li span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.leaderboard-list li strong {
  color: var(--gold);
  text-align: right;
}
.leaderboard-list .empty-rank {
  display: flex;
  color: rgba(246, 242, 232, 0.42);
}
.rating-summary p {
  margin: 10px 0 0;
  color: rgba(246, 242, 232, 0.5);
  font-size: 10px;
  line-height: 1.5;
}
.center-stage {
  position: relative;
  min-width: 0;
  min-height: 620px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 34px;
  overflow: hidden;
}
.center-title {
  position: relative;
  z-index: 8;
  margin-top: -84px;
  text-align: center;
}
.center-title > svg {
  color: var(--gold);
}
.center-title h1 {
  margin: 8px 0 6px;
  font:
    900 clamp(48px, 6vw, 88px)/0.95 Arial Black,
    'Microsoft YaHei',
    sans-serif;
  color: var(--paper);
  text-shadow: 6px 6px 0 rgba(5, 22, 16, 0.5);
}
.center-title p {
  margin: 0;
  color: rgba(246, 242, 232, 0.65);
  font-size: 12px;
  font-weight: 700;
}
.suit-orbit {
  position: absolute;
  left: 50%;
  top: 43%;
  border: 1px solid rgba(239, 187, 71, 0.28);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}
.orbit-outer {
  width: min(42vw, 530px);
  aspect-ratio: 1;
  animation: orbit-spin 32s linear infinite;
}
.orbit-outer span {
  position: absolute;
  font-size: 22px;
  color: rgba(246, 242, 232, 0.35);
}
.orbit-outer span:nth-child(1) {
  left: 50%;
  top: -13px;
}
.orbit-outer span:nth-child(2) {
  right: -9px;
  top: 50%;
  color: rgba(216, 74, 74, 0.55);
}
.orbit-outer span:nth-child(3) {
  left: 50%;
  bottom: -13px;
  color: rgba(216, 74, 74, 0.55);
}
.orbit-outer span:nth-child(4) {
  left: -9px;
  top: 50%;
}
.orbit-inner {
  width: min(30vw, 380px);
  aspect-ratio: 1;
  border-color: rgba(246, 242, 232, 0.12);
  animation: orbit-spin-reverse 24s linear infinite;
}
.orbit-inner i {
  position: absolute;
  width: 7px;
  height: 7px;
  background: var(--gold);
  transform: rotate(45deg);
}
.orbit-inner i:nth-child(1) {
  left: 13%;
  top: 13%;
}
.orbit-inner i:nth-child(2) {
  right: 13%;
  top: 13%;
}
.orbit-inner i:nth-child(3) {
  right: 13%;
  bottom: 13%;
}
.orbit-inner i:nth-child(4) {
  left: 13%;
  bottom: 13%;
}
.orbit-card {
  position: absolute;
  width: 72px;
  aspect-ratio: 5/7;
  padding: 8px;
  display: grid;
  align-content: space-between;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid #fff;
  box-shadow: 5px 7px 0 rgba(4, 18, 13, 0.38);
  font:
    900 17px/1 Arial Black,
    sans-serif;
  animation: card-float 4.8s ease-in-out infinite;
}
.orbit-card i {
  justify-self: end;
  font-style: normal;
  font-size: 24px;
}
.card-two,
.card-three {
  color: #b82e3c;
}
.card-one {
  left: 9%;
  top: 20%;
  transform: rotate(-13deg);
}
.card-two {
  right: 9%;
  top: 17%;
  transform: rotate(11deg);
  animation-delay: -1.1s;
}
.card-three {
  left: 13%;
  bottom: 25%;
  transform: rotate(9deg);
  animation-delay: -2.2s;
}
.card-four {
  right: 12%;
  bottom: 23%;
  transform: rotate(-10deg);
  animation-delay: -3.3s;
}
.match-controls {
  position: relative;
  z-index: 9;
  width: min(390px, 82%);
  display: grid;
  gap: 10px;
}
.mode-selector {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid rgba(246, 242, 232, 0.4);
  color: rgba(246, 242, 232, 0.4);
}
.mode-selector button {
  min-height: 44px;
  border: 0;
  border-right: 1px solid currentColor;
  background: rgba(10, 32, 23, 0.8);
  color: var(--paper);
  display: grid;
  place-content: center;
  gap: 2px;
}
.mode-selector button:last-child {
  border-right: 0;
}
.mode-selector button[aria-pressed='true'] {
  background: var(--color-command);
  color: var(--color-table-deep);
}
.mode-selector strong {
  font-size: 13px;
}
.mode-selector span {
  font-size: 10px;
  opacity: 0.65;
}
.match-button {
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin: 4px 0;
  border: 1px solid var(--color-command);
  border-radius: 0;
  background: var(--color-command);
  color: var(--color-table-deep);
  font-size: 15px;
  font-weight: 900;
}
.match-button:hover:not(:disabled) {
  transform: translateY(-2px);
}
.match-button:active:not(:disabled) {
  transform: scale(0.98);
}
.match-button.cancel-match {
  border-color: var(--color-danger);
  background: var(--color-cream);
  color: #9f1711;
}
.match-button.cancel-match:hover:not(:disabled) {
  background: #fff0ee;
  transform: translateY(-2px);
}
.match-controls > span {
  text-align: center;
  color: rgba(246, 242, 232, 0.48);
  font-size: 10px;
}
.room-rail > header {
  min-height: 72px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}
.room-rail > header > svg {
  color: var(--gold);
}
.room-rail header div {
  display: grid;
  gap: 2px;
}
.room-rail header span {
  color: var(--gold);
  font-size: 9px;
  font-weight: 900;
}
.room-rail h2 {
  margin: 0;
  font-size: 17px;
}
.room-tool {
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}
.room-tool h3,
.room-tool label {
  display: block;
  margin: 0 0 11px;
  font-size: 12px;
  font-weight: 900;
}
.room-tool .primary-button,
.room-tool .secondary-button {
  margin-top: 12px;
}
.join-tool {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: stretch;
  gap: 10px;
  border-bottom: 0;
}
.join-tool label,
.join-tool .room-code-input,
.join-tool .secondary-button {
  width: 100%;
  margin: 0;
}
.room-code-input {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--color-command);
  border-radius: 0;
  background: var(--color-cream);
  color: var(--color-table-deep);
  text-align: center;
  font:
    900 22px/1 ui-monospace,
    monospace;
  letter-spacing: 6px;
}
.primary-button,
.secondary-button {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 15px;
  border: 1px solid var(--color-command);
  border-radius: 0;
  font-weight: 900;
}
.primary-button {
  background: var(--color-command);
  color: var(--color-table-deep);
}
.secondary-button {
  background: transparent;
  color: var(--color-command);
}
.primary-button:hover:not(:disabled),
.secondary-button:hover:not(:disabled) {
  transform: translateY(-2px);
}
.primary-button:active:not(:disabled),
.secondary-button:active:not(:disabled) {
  transform: scale(0.98);
}
.wide {
  width: 100%;
}
.active-room-header {
  justify-content: space-between;
}
.active-room-header h2 {
  color: var(--gold);
  font:
    900 23px/1 ui-monospace,
    monospace;
  letter-spacing: 3px;
}
.copy-feedback {
  min-height: 0;
  display: block;
  padding: 0 16px;
  color: var(--color-accent);
  font-size: 10px;
  text-align: right;
}
.copy-feedback:not(:empty) {
  min-height: 26px;
  padding-top: 7px;
}
.copy-failed {
  color: #ff9b94;
}
.copy-icon,
.close-button {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(246, 242, 232, 0.26);
  background: transparent;
  color: var(--paper);
}
.compact-members {
  padding: 14px;
  border-bottom: 1px solid var(--line);
}
.rail-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.rail-section-title h3 {
  margin: 0;
  font-size: 12px;
}
.rail-section-title span {
  color: var(--gold);
  font-size: 11px;
  font-weight: 900;
}
.compact-members ol {
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 5px;
  max-height: 245px;
  overflow: auto;
}
.compact-members li {
  min-height: 50px;
  display: grid;
  grid-template-columns: 25px 34px minmax(0, 1fr) 10px 44px;
  align-items: center;
  gap: 6px;
  padding: 5px;
  background: rgba(246, 242, 232, 0.06);
}
.seat-number {
  color: rgba(246, 242, 232, 0.35);
  font: 800 10px/1 monospace;
}
.mini-avatar {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  background: var(--paper);
  color: var(--ink);
  font-weight: 900;
}
