content.text:
* {
  box-sizing: border-box;
}
:root {
  font-family: Inter, 'Microsoft YaHei', 'Helvetica Neue', system-ui, sans-serif;
  color: #ffffff;
  background: #23280b;
  font-synthesis: none;
  --color-canvas: #d9cdad;
  --color-table: #465016;
  --color-table-deep: #23280b;
  --color-moss: #616a37;
  --color-charcoal: #2f2e25;
  --color-leather: #764b41;
  --color-leather-dark: #594d40;
  --color-cream: #ffffff;
  --color-accent: #ccff00;
  --color-command: #c6a15b;
  --color-command-hover: #d2b06c;
  --color-danger: #ff3b30;
  --color-secondary: #0057ff;
  --color-focus: #00ff00;
  --ink: var(--color-table-deep);
  --ink-soft: var(--color-charcoal);
  --table: var(--color-table);
  --table-deep: var(--color-table-deep);
  --paper: var(--color-cream);
  --muted: var(--color-canvas);
  --gold: var(--color-accent);
  --gold-deep: var(--color-moss);
  --red: var(--color-danger);
  --green: var(--color-accent);
  --blue: var(--color-secondary);
  --line: rgba(255, 255, 255, 0.18);
  --control-transition: 160ms ease;
}
body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
}
button,
input,
select,
textarea {
  font: inherit;
  letter-spacing: 0;
}
button {
  cursor: pointer;
  transition:
    transform var(--control-transition),
    background-color var(--control-transition),
    border-color var(--control-transition),
    color var(--control-transition);
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
a:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}
.home-shell {
  min-height: 100vh;
  display: grid;
  grid-template-rows: 68px minmax(680px, 1fr) 42px;
  background: var(--ink);
}
.lobby-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 clamp(15px, 2.5vw, 38px);
  border-bottom: 1px solid rgba(246, 242, 232, 0.13);
  background: var(--ink);
  z-index: 50;
}
.brand-lockup,
.header-actions,
.service-state,
.home-footer {
  display: flex;
  align-items: center;
}
.brand-lockup {
  gap: 11px;
}
.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  color: var(--ink);
  background: var(--gold);
  border: 1px solid #ffe091;
  font:
    900 14px/1 Arial Black,
    sans-serif;
  transform: rotate(-3deg);
}
.brand-lockup div {
  display: grid;
  gap: 1px;
}
.brand-lockup strong {
  font-size: 16px;
}
.brand-lockup span:last-child {
  color: rgba(246, 242, 232, 0.55);
  font-size: 11px;
  font-weight: 700;
}
.header-actions {
  gap: 10px;
}
.audio-control {
  position: relative;
}
.header-icon-button {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid var(--color-command);
  background: transparent;
  color: var(--color-command);
}
.audio-popover {
  position: absolute;
  z-index: 90;
  top: calc(100% + 10px);
  right: 0;
  width: 220px;
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--color-command);
  background: var(--color-table-deep);
  color: var(--color-cream);
