.info-row span {
  color: #66675c;
  font-size: 11px;
}
.info-row strong {
  color: var(--color-charcoal);
  font-size: 13px;
  font-weight: 700;
}
.confirmation-actions {
  display: flex;
  gap: 12px;
}
.accept-button,
.decline-button {
  flex: 1;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 0;
  font-size: 14px;
  font-weight: 900;
}
.accept-button {
  border: 1px solid var(--color-command);
  background: var(--color-command);
  color: var(--color-table-deep);
}
.accept-button:hover {
  transform: translateY(-2px);
}
.decline-button {
  border: 1px solid var(--color-danger);
  background: var(--color-cream);
  color: #9f1711;
}
.decline-button:hover {
  background: #fff0ee;
  transform: translateY(-2px);
}
.accepted-notice {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px;
  border: 1px solid var(--color-table);
  background: #eff5d8;
  color: var(--color-table-deep);
  font-size: 13px;
  font-weight: 700;
}
.leave-room-button {
  min-height: 44px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid rgba(216, 74, 74, 0.55);
  background: transparent;
  color: #ffc3c3;
  font-size: 10px;
  font-weight: 900;
}
.leave-room-button:hover:not(:disabled) {
  background: rgba(216, 74, 74, 0.12);
}
.game-started {
  min-height: 180px;
  display: grid;
  place-content: center;
  gap: 5px;
  text-align: center;
}
.game-started strong {
  color: var(--gold);
}
.game-started span {
  font-size: 11px;
  color: rgba(246, 242, 232, 0.6);
}
.home-feedback {
  position: absolute;
  left: 50%;
  bottom: 10px;
  z-index: 20;
  min-width: 280px;
  max-width: 560px;
  transform: translateX(-50%);
  padding: 8px 13px;
  background: rgba(7, 25, 18, 0.9);
  border-left: 3px solid var(--gold);
  text-align: center;
  color: rgba(246, 242, 232, 0.75);
  font-size: 10px;
}
.home-feedback[role='alert'] {
  border-left-color: var(--red);
  color: #ffd2d2;
}
.home-footer {
  justify-content: space-between;
  gap: 18px;
  padding: 0 clamp(15px, 2.5vw, 38px);
  color: rgba(246, 242, 232, 0.44);
  font-size: 10px;
  font-weight: 700;
}
.identity-loading {
  min-height: 620px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 13px;
  text-align: center;
}
.identity-loading h1 {
  margin: 5px 0 0;
  font-size: 30px;
}
.identity-loading p {
  margin: 0;
  color: rgba(246, 242, 232, 0.6);
}
.identity-loading > i {
  width: 34px;
  height: 34px;
  border: 3px solid rgba(246, 242, 232, 0.2);
  border-top-color: var(--gold);
  border-radius: 50%;
  animation: orbit-spin 1s linear infinite;
}
.overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(6, 10, 7, 0.72);
  display: flex;
  align-items: stretch;
  justify-content: flex-start;
}
.rules-drawer {
  width: min(480px, 100%);
  padding: 24px;
  background: var(--paper);
  color: var(--ink);
  overflow: auto;
  box-shadow: 10px 0 0 rgba(239, 187, 71, 0.35);
}
.rules-drawer > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid #c9c5ba;
  padding-bottom: 16px;
}
.rules-drawer header span,
.auth-modal > span {
  color: #8c6419;
  font-size: 10px;
  font-weight: 900;
}
.rules-drawer h2,
.auth-modal h2 {
  margin: 4px 0 0;
  font-size: 25px;
}
.rules-drawer .close-button,
.auth-modal .close-button {
  color: var(--ink);
  border-color: #8b8f89;
}
.rules-drawer nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 18px 0;
}
.rules-drawer nav a {
  min-height: 44px;
  display: flex;
  align-items: center;
  padding: 0 12px;
  border: 1px solid #8b8f89;
  color: var(--ink);
  font-size: 12px;
  text-decoration: none;
  font-weight: 800;
}
.rules-drawer section {
  padding: 15px 0;
  border-top: 1px solid #d5d1c7;
}
.rules-drawer h3 {
  margin: 0 0 7px;
  font-size: 16px;
}
.rules-drawer p {
  margin: 0;
  color: #555c57;
  font-size: 13px;
  line-height: 1.65;
}
.rules-tutorial-button {
  width: 100%;
  margin: 10px 0 16px;
}
.rules-note {
  padding: 15px;
  background: #e8e3d8;
}
.auth-overlay {
  align-items: center;
  justify-content: center;
  padding: 18px;
}
.auth-modal {
  position: relative;
  width: min(440px, 100%);
  padding: 30px;
  background: var(--paper);
  color: var(--ink);
  border-top: 5px solid var(--gold);
  box-shadow: 10px 10px 0 rgba(0, 0, 0, 0.35);
}
.auth-modal > .close-button {
  position: absolute;
  right: 14px;
  top: 14px;
}
.auth-modal > svg {
  color: var(--gold-deep);
}
.auth-modal p {
  margin: 15px 0 22px;
  color: #555c57;
  font-size: 13px;
  line-height: 1.65;
}
.auth-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin: 18px 0;
  border: 1px solid #8b8f89;
}
.auth-tabs button {
  min-height: 44px;
  border: 0;
  border-right: 1px solid #8b8f89;
  background: transparent;
  color: var(--ink);
  font-weight: 900;
}
.auth-tabs button:last-child {
  border-right: 0;
}
.auth-tabs button[aria-selected='true'] {
  background: var(--ink);
  color: var(--paper);
}
.auth-form {
  display: grid;
  gap: 7px;
}
.auth-form > label,
.name-selects label {
  font-size: 11px;
  font-weight: 900;
}
.auth-form input,
.name-selects select {
  width: 100%;
  min-height: 44px;
  padding: 0 11px;
  border: 1px solid var(--color-command);
  border-radius: 0;
  background: var(--color-cream);
  color: var(--color-table-deep);
}
.auth-form > small {
  margin-bottom: 5px;
  color: #666c67;
  font-size: 10px;
}
.name-selects {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin-top: 7px;
}
.name-selects label {
  display: grid;
  gap: 6px;
}
.name-preview {
  min-height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #e8e3d8;
  font-size: 13px;
  font-weight: 900;
}
.auth-modal .recovery-warning {
  margin: 2px 0 8px;
  color: #8d3d35;
  font-size: 10px;
}
.auth-modal .auth-error {
  margin: 2px 0;
  padding: 9px;
  background: #f5d8d5;
  color: #8c2626;
  font-size: 11px;
}
.auth-form .primary-button {
  margin-top: 8px;
}
@keyframes orbit-spin {
  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}
@keyframes orbit-spin-reverse {
  to {
    transform: translate(-50%, -50%) rotate(-360deg);
  }
}
@keyframes card-float {
  0%,
  100% {
    margin-top: 0;
  }
  50% {
    margin-top: -10px;
  }
}
.tutorial-highlight {
  position: relative;
  z-index: 65;
  outline: 2px solid var(--color-command);
  outline-offset: 5px;
}
.tutorial-guide {
  position: fixed;
  z-index: 70;
  right: clamp(18px, 3vw, 44px);
  bottom: 58px;
  width: min(390px, calc(100vw - 32px));
  padding: 18px;
  border: 1px solid var(--color-command);
  background: var(--color-table-deep);
  color: var(--color-cream);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.35);
  pointer-events: auto;
}
.tutorial-guide header,
.tutorial-guide footer,
.tutorial-guide footer > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.tutorial-guide header > span {
  color: var(--color-command);
  font-size: 10px;
  font-weight: 900;
}
.tutorial-guide header button,
.tutorial-guide footer button {
  min-width: 44px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--color-command);
  border-radius: 0;
  background: transparent;
  color: var(--color-command);
}
.tutorial-guide h2 {
  margin: 15px 0 8px;
  font-size: 22px;
}
.tutorial-guide p {
  margin: 0;
  color: rgba(255, 255, 255, 0.75);
  font-size: 13px;
  line-height: 1.65;
}
.tutorial-progress {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 4px;
  margin: 18px 0;
}
.tutorial-progress i {
  height: 3px;
  background: rgba(255, 255, 255, 0.2);
}
.tutorial-progress i.is-complete {
  background: var(--color-command);
}
.tutorial-guide footer .tutorial-skip {
  padding: 0 12px;
  border-color: transparent;
  color: rgba(255, 255, 255, 0.65);
}
.tutorial-guide footer .tutorial-next {
  min-width: 104px;
  padding: 0 12px;
  background: var(--color-command);
  color: var(--color-table-deep);
  font-weight: 900;
}
@keyframes effect-shake {
  25% {
    transform: translateX(-3px);
  }
  50% {
    transform: translateX(3px);
  }
  75% {
    transform: translateX(-2px);
  }
}
@keyframes combatant-enter {
  from {
    opacity: 0;
    transform: translateX(-18px);
  }
}
@keyframes combat-card-arrive {
  from {
    opacity: 0;
    transform: translateY(80px) scale(0.84);
  }
}
@keyframes combat-burst {
  from {
    opacity: 0;
    transform: translate(-80px, -50%) rotate(0) scale(0.2);
  }
  55% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translate(0, -50%) rotate(135deg) scale(1.6);
  }
}
@keyframes combat-target-impact {
  25% {
    transform: translateX(5px);
  }
  50% {
    transform: translateX(-4px);
  }
  75% {
    transform: translateX(2px);
  }
}
@keyframes combat-delta {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.8);
  }
  35% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translateY(-34px) scale(1.1);
  }
}
@keyframes combat-meter-change {
  from {
    width: var(--meter-from);
  }
  to {
    width: var(--meter-to);
  }
}
@keyframes played-card-enter {
  from {
    opacity: 0;
    transform: translateY(90px) scale(0.82)
      rotate(calc((var(--card-index) - (var(--card-count) - 1) / 2) * 3deg));
  }
}
